 function getMistakes(){try{const a=JSON.parse(localStorage.getItem(mistakeKey)||"[]");return Array.isArray(a)?a.filter(x=>Array.isArray(x.q)&&typeof x.q[0]==="string"):[]}catch(e){return[]}}
 function saveMistakes(a){try{localStorage.setItem(mistakeKey,JSON.stringify(a.slice(-500)))}catch(e){}}
 function addMistake(q){const a=getMistakes();if(!a.some(x=>x.q[0]===q[0]))a.push({q:Array.from(q),addedAt:Date.now()});saveMistakes(a)}
 function removeMistake(stem){saveMistakes(getMistakes().filter(x=>x.q[0]!==stem))}
