 const nhpcRandomBatch1=[["Which structure forms the primary passive restraint against anterior translation of the tibia?","Tibia अगाडि सर्ने movement रोक्ने मुख्य passive restraint कुन हो?",["Anterior cruciate ligament","Patellar tendon","Medial meniscus only","Achilles tendon"],0,"The ACL helps restrain anterior tibial translation and contributes to rotational stability.","ACL ले tibia को anterior translation रोक्न र rotational stability मा सहयोग गर्छ।","Section 1"],["Which muscle is the prime mover for ankle dorsiflexion?","Ankle dorsiflexion को मुख्य muscle कुन हो?",["Tibialis anterior","Gastrocnemius","Soleus","Peroneus longus"],0,"Tibialis anterior is a major ankle dorsiflexor.","Tibialis anterior ankle dorsiflexion को मुख्य muscle हो।","Section 1"],["Which spinal nerve roots are commonly associated with the Achilles tendon reflex?","Achilles tendon reflex कुन spinal nerve roots सँग सम्बन्धित छ?",["S1–S2, mainly S1","C5–C6","L2–L3","T1–T2"],0,"The ankle jerk is primarily S1 with contribution from S2.","Ankle jerk मुख्यतः S1 र केही S2 बाट हुन्छ।","Section 1"],["What type of joint is the glenohumeral joint?","Glenohumeral joint कुन प्रकारको joint हो?",["Ball-and-socket synovial joint","Hinge joint","Pivot joint","Saddle joint"],0,"The shoulder is a ball-and-socket joint allowing movement in multiple planes.","Shoulder ball-and-socket synovial joint हो, धेरै plane मा चल्छ।","Section 1"],["Which muscle is most associated with knee extension?","Knee extension को मुख्य muscle group कुन हो?",["Quadriceps femoris","Hamstrings","Gluteus medius","Tibialis posterior"],0,"The quadriceps femoris group produces knee extension.","Quadriceps femoris ले knee extension गर्छ।","Section 1"],["Which plane divides the body into left and right portions?","शरीरलाई left र right भागमा विभाजन गर्ने plane कुन हो?",["Sagittal plane","Frontal plane","Transverse plane","Oblique plane only"],0,"The sagittal plane divides the body into right and left portions.","Sagittal plane ले शरीरलाई दायाँ र बायाँ भागमा बाँड्छ।","Section 1"],["Which type of muscle contraction occurs when a muscle lengthens while controlling a load?","Load नियन्त्रण गर्दा muscle लम्बिँदै काम गर्ने contraction कुन हो?",["Eccentric","Concentric","Isometric","Isokinetic only"],0,"Eccentric contraction produces force while the muscle-tendon unit lengthens.","Eccentric contraction मा muscle लम्बिँदै force उत्पादन गर्छ।","Section 1"],["What is the main role of synovial fluid?","Synovial fluid को मुख्य काम के हो?",["Lubricate the joint and help nourish articular cartilage","Connect muscle to bone","Transmit nerve impulses","Form red blood cells"],0,"Synovial fluid reduces friction and supports nutrition of articular cartilage.","Synovial fluid ले friction घटाउँछ र cartilage लाई पोषणमा सहयोग गर्छ।","Section 1"],["Which exercise is commonly used to improve quadriceps activation after knee surgery when movement is limited?","Knee surgery पछि movement सीमित हुँदा quadriceps activation का लागि कुन exercise प्रयोग हुन्छ?",["Quadriceps setting/isometric contraction","Maximal jumping","Deep loaded squat immediately","Repeated pivoting"],0,"Quadriceps sets activate the muscle with minimal knee movement, if permitted by precautions.","Precaution अनुमति भए quadriceps set ले कम knee movement मा muscle activate गर्छ।","Section 2"],["What is the usual purpose of a goniometer's stationary arm?","Goniometer को stationary arm को काम के हो?",["Align with the proximal segment/reference axis","Measure pulse rate","Apply resistance during MMT","Record body temperature"],0,"The stationary arm is aligned with the proximal segment or anatomical reference.","Stationary arm proximal segment वा anatomical reference सँग मिलाइन्छ।","Section 2"],["In MMT, grade 3 generally indicates which ability?","MMT grade 3 ले सामान्यतया कुन क्षमता जनाउँछ?",["Full available ROM against gravity without added resistance","No palpable contraction","Full ROM against maximal resistance","Movement only in gravity-eliminated position"],0,"Grade 3 is movement through available range against gravity without added resistance.","Grade 3 मा gravity विरुद्ध उपलब्ध ROM पूरा हुन्छ, थप resistance बिना।","Section 2"],["Which principle is important when progressing resistance exercise?","Resistance exercise बढाउँदा कुन principle महत्त्वपूर्ण हुन्छ?",["Progress gradually according to response and goals","Increase load regardless of pain or form","Train to failure in every patient","Ignore recovery"],0,"Progressive overload should be individualized and monitored for symptoms, technique and recovery.","Progressive overload बिरामीको लक्षण, technique र recovery अनुसार क्रमशः बढाउनुपर्छ।","Section 2"],["Which gait phase begins immediately after initial contact?","Initial contact पछि gait cycle को कुन phase आउँछ?",["Loading response","Mid swing","Terminal swing","Pre-swing"],0,"Loading response follows initial contact and accepts body weight.","Initial contact पछि loading response मा body weight स्वीकार हुन्छ।","Section 2"],["What is the purpose of a walking aid fitted at the correct height?","ठीक उचाइमा मिलाइएको walking aid को उद्देश्य के हो?",["Improve support and reduce unsafe loading or balance demand","Replace all muscle activity","Guarantee no falls","Correct every deformity"],0,"A correctly fitted aid can improve stability and support when selected and taught appropriately.","ठीक aid ले उपयुक्त छनोट र training भए stability तथा support सुधार्छ।","Section 2"],["Which position is commonly used to reduce pressure on the sacrum in a bedbound patient?","Bedbound बिरामीमा sacrum को pressure घटाउन कुन position उपयोगी हुन्छ?",["Regular repositioning with individualized pressure-relieving positions","Keep supine without movement all day","Place a hard ring directly under the sacrum","Massage persistent redness vigorously"],0,"Individualized repositioning and pressure redistribution help prevent pressure injury.","व्यक्तिगत repositioning र pressure redistribution ले pressure injury रोक्न सहयोग गर्छ।","Section 2"],["What does the RPE scale help a therapist monitor during exercise?","Exercise गर्दा RPE scale ले के monitor गर्न मद्दत गर्छ?",["Perceived exercise intensity","Joint range in degrees","Bone density","Reflex grade"],0,"RPE records the patient's subjective exercise effort and helps guide intensity.","RPE ले बिरामीले महसुस गरेको exercise effort मापन गरी intensity मिलाउन मद्दत गर्छ।","Section 2"],["Which finding after a fracture may suggest neurovascular compromise and needs urgent assessment?","Fracture पछि neurovascular compromise को संकेत कुन हो?",["Increasing pain with pallor, numbness or reduced distal pulse","Mild expected bruising only","Stable swelling that is improving","Normal movement and sensation"],0,"Pain escalation, pallor, sensory change or reduced pulse can signal compromised circulation or nerves.","दुखाइ बढ्नु, फिक्का हुनु, sensation बदलिनु वा pulse घट्नु circulation/nerve समस्या हुन सक्छ।","Section 3"],["What is the main rehabilitation concern after prolonged immobilization of a joint?","Joint लामो समय immobilize हुँदा मुख्य rehabilitation concern के हो?",["Stiffness, weakness and reduced function","Improved endurance automatically","Permanent increase in ROM","No muscle changes"],0,"Immobilization can cause stiffness, muscle atrophy and functional decline.","Immobilization ले stiffness, muscle atrophy र function घटाउन सक्छ।","Section 3"],["Which condition is characterized by inflammation of a tendon?","Tendon को inflammation लाई के भनिन्छ?",["Tendinitis/tendinopathy (clinical term depends on pathology)","Bursitis","Arthrosis","Neuropathy"],0,"Tendinitis refers to tendon inflammation; tendinopathy is often used for broader tendon pathology.","Tendinitis tendon inflammation हो; tendinopathy व्यापक tendon समस्या जनाउन प्रयोग हुन्छ।","Section 3"],["What is a key early goal after lower-limb amputation, when medically appropriate?","Lower-limb amputation पछि medically appropriate हुँदा प्रारम्भिक लक्ष्य के हो?",["Prevent contracture and maintain strength/function","Keep the residual limb dependent all day","Avoid all positioning","Begin unsupervised prosthetic walking immediately"],0,"Positioning, contracture prevention, residual-limb care and general strengthening are common early goals.","Positioning, contracture रोकथाम, residual limb care र strengthening प्रारम्भिक लक्ष्य हुन्।","Section 3"],["Which intervention is commonly used for edema management when appropriate?","उपयुक्त अवस्थामा edema management का लागि कुन intervention प्रयोग हुन सक्छ?",["Elevation, movement and prescribed compression after screening","Tight unmonitored bandaging","Prolonged dependency","Heat over unexplained acute swelling"],0,"Edema management depends on cause and may include elevation, muscle-pump activity and appropriate compression.","कारणअनुसार elevation, muscle pump र उचित compression प्रयोग हुन सक्छ।","Section 3"],["Which assessment is essential before prescribing exercise for a patient with known cardiac disease?","Cardiac disease भएको बिरामीलाई exercise दिनुअघि के आवश्यक छ?",["Review medical stability, symptoms, risk and prescribed limits","Ignore chest symptoms","Use maximal exercise as the first test","Stop all activity permanently"],0,"Exercise must be individualized using medical status, symptoms, risk and relevant precautions.","Medical status, symptoms, risk र precaution अनुसार exercise व्यक्तिगत बनाउनुपर्छ।","Section 3"],["What is an important rehabilitation focus for an older adult with recurrent falls?","बारम्बार लड्ने वृद्ध बिरामीमा rehabilitation को महत्त्वपूर्ण focus के हो?",["Balance, strength, gait, environment and fall-risk review","Only passive massage","Avoid walking assessment","Train only upper-limb flexibility"],0,"Multifactorial fall prevention addresses strength, balance, gait, medications and environment as appropriate.","Fall prevention मा strength, balance, gait, औषधि र वातावरण जाँचिन्छ।","Section 3"],["Which sign is a warning of possible deep vein thrombosis?","DVT को सम्भावित warning sign कुन हो?",["Unilateral calf swelling, warmth or tenderness","Bilateral painless finger stiffness","Isolated shoulder weakness","Normal symmetrical calf"],0,"Unilateral swelling, warmth and tenderness may indicate DVT; urgent medical assessment is needed.","एकतर्फी calf swelling, warmth र tenderness DVT हुन सक्छ; urgent assessment चाहिन्छ।","Section 3"],["What is the priority when a patient develops sudden severe breathlessness and chest pain during therapy?","Therapy गर्दा अचानक गम्भीर श्वासकष्ट र छाती दुखेमा प्राथमिकता के हो?",["Stop therapy and activate urgent medical response","Continue at lower intensity without assessment","Give vigorous massage","Ask the patient to walk it off"],0,"Possible cardiopulmonary emergency requires stopping activity and urgent response.","सम्भावित cardiopulmonary emergency मा therapy रोक्दै तत्काल सहायता बोलाउनुपर्छ।","Section 4"],["Which technique may help a patient with COPD control breathlessness?","COPD बिरामीलाई श्वासकष्ट नियन्त्रणमा कुन technique सहयोगी हुन सक्छ?",["Pursed-lip breathing","Breath holding","Rapid forced inhalation","Valsalva during walking"],0,"Pursed-lip breathing may help prolong expiration and reduce breathlessness for some patients.","Pursed-lip breathing ले केही बिरामीमा expiration लम्ब्याई श्वासकष्ट घटाउन सक्छ।","Section 4"],["What is the main aim of airway clearance techniques?","Airway clearance technique को मुख्य उद्देश्य के हो?",["Mobilize and remove secretions when indicated","Increase airway obstruction","Replace oxygen in every patient","Stop all coughing"],0,"Airway clearance techniques assist secretion mobilization in selected patients.","Airway clearance ले चयनित बिरामीमा secretion mobilize गर्न मद्दत गर्छ।","Section 4"],["Which developmental skill is commonly expected before independent walking in typical development?","सामान्य विकासमा स्वतन्त्र हिँड्नुअघि कुन skill प्रायः आउँछ?",["Pulling to stand and cruising along support","Independent running","Jumping with both feet","Stair climbing without support"],0,"Pull-to-stand and supported cruising typically precede independent walking, though timing varies.","सहारा समातेर उभिने र cruising प्रायः स्वतन्त्र हिँड्नुअघि आउँछ; समय फरक हुन सक्छ।","Section 4"],["What is a key physiotherapy goal for a child with cerebral palsy?","Cerebral palsy भएको बच्चामा physiotherapy को मुख्य लक्ष्य के हो?",["Improve functional activity, participation and caregiver-supported mobility","Normalize every movement pattern at any cost","Prevent all play","Use one identical plan for every child"],0,"Goals are individualized around function, participation, mobility, comfort and family priorities.","लक्ष्य बच्चाको function, participation, mobility, आराम र परिवारको प्राथमिकताअनुसार हुन्छ।","Section 4"],["Which positioning may help reduce aspiration risk during feeding for a patient with dysphagia, as advised by the team?","Dysphagia भएको बिरामीलाई feeding गर्दा aspiration risk घटाउन कुन positioning प्रयोग हुन सक्छ?",["Upright supported sitting","Flat supine","Head hanging backward","Unsupervised feeding while drowsy"],0,"Upright supported positioning and individualized swallowing recommendations may reduce risk.","Upright supported position र individualized swallowing advice ले जोखिम घटाउन सक्छ।","Section 4"],["What should be monitored during early mobilization after stroke?","Stroke पछि early mobilization गर्दा के monitor गर्नुपर्छ?",["Blood pressure, symptoms, balance and neurological tolerance","Only shoe colour","No need to check fatigue","Maximal exertion without support"],0,"Monitor physiological response, symptoms, safety and neurological tolerance during mobilization.","Mobilization गर्दा physiological response, symptoms, safety र neurological tolerance हेर्नुपर्छ।","Section 4"]];
